// @vitest-environment node
/**
 * Real-world fixtures: résumés exported by real tools (see tests/fixtures/real/MISSING.md).
 * A PDF is scored when it is in real/pdf/ with its expected JSON. Scanned files are checked for the message.
 */
import { describe, it, expect } from 'vitest';
import { readdirSync, existsSync, writeFileSync, readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { scoreOne, Score } from './score';
import { importResume, NO_TEXT_MESSAGE } from '../../src/services/importResume';

const dir = join(dirname(fileURLToPath(import.meta.url)), 'real');
const expectedFiles = readdirSync(join(dir, 'expected')).filter((f) => f.endsWith('.json'));
const meta = expectedFiles.map((f) => JSON.parse(readFileSync(join(dir, 'expected', f), 'utf8')) as { id: string; kind: string });
const textIds = meta.filter((m) => m.kind !== 'scanned').map((m) => m.id).sort();
const scannedIds = meta.filter((m) => m.kind === 'scanned').map((m) => m.id);

describe('real-world PDFs', () => {
  it('scores each real PDF that is present, and writes the report', async () => {
    const scores: Score[] = [];
    const missing: string[] = [];
    for (const id of textIds) {
      if (existsSync(join(dir, 'pdf', `${id}.pdf`))) scores.push(await scoreOne(dir, id));
      else missing.push(id);
    }
    const keys = scores.length ? Object.keys(scores[0].fields) : [];
    const pct = (n: number) => `${Math.round(n * 100)}`.padStart(3);
    const lines = [
      `real-world PDFs scored: ${scores.length} of ${textIds.length} (missing: ${missing.length})`,
      scores.length ? ['fixture'.padEnd(28), ...keys, 'overall'].join(' | ') : '(no PDFs present yet; see MISSING.md)',
      ...scores.map((s) => [s.id.padEnd(28), ...keys.map((k) => pct(s.fields[k])), pct(s.overall)].join(' | ')),
      scores.length ? `mean overall: ${Math.round((scores.reduce((a, s) => a + s.overall, 0) / scores.length) * 100)}%` : '',
      missing.length ? `not yet scored: ${missing.join(', ')}` : '',
    ].filter(Boolean);
    writeFileSync(join(dir, 'report.txt'), lines.join('\n') + '\n');
    console.log(lines.join('\n'));
    expect(scores.length + missing.length).toBe(textIds.length);
  }, 180_000);

  for (const id of scannedIds) {
    it(`${id}: an image-only PDF gives the clear message, not an empty resume`, async () => {
      const path = join(dir, 'pdf', `${id}.pdf`);
      if (!existsSync(path)) return; // generated by build-real.py
      const bytes = readFileSync(path);
      const file = new File([bytes], `${id}.pdf`, { type: 'application/pdf' });
      const result = await importResume(file);
      expect(result.success).toBe(false);
      expect(result.errors).toEqual([NO_TEXT_MESSAGE]);
    });
  }
});
